			/**
			 * 입소기간 구하기(년 월 일)
			 * @param startDate, endDate (시작일자, 종료일자) 년 월 일을 넘김
			 */
			function getEntrncPrd(bgngYmd, trmnYmd) {
			    
			    var strDate = new Date(bgngYmd.substring(0,4), bgngYmd.substring(4,6), bgngYmd.substring(6,8));
			    var endDate = new Date(trmnYmd.substring(0,4), trmnYmd.substring(4,6), trmnYmd.substring(6,8));
			    
			    var currDay = 24 * 60 * 60 * 1000; // 시 * 분 * 초 * 밀리세컨
			    var currMonth = currDay * 30; //월
			    var currYear = currMonth * 12; //년

			    var diff = endDate.getTime() - strDate.getTime() + currDay; //milliseconds
			    
			    var yy = parseInt(diff/currYear);
			    var mm = parseInt(diff/currMonth) % 12;
			    var dd = parseInt(diff/currDay) - (yy * 365 + mm * 30);

			    return { PRD_YR : yy,
			             PRD_MM : mm,
			             PRD_DD : dd,
			            };     
			}
			    

