			/**
			 * 자립지원수당 조건 check
			 * @param 
			 */
			function checkSlfrlPensn(){

			    var dsList = app.lookup("dsList");
			    
			    var maxTrmnYmd = dsList.getMax("CASE_TRMN_YMD"); //최근퇴소일자
			    var minBgngYmd = dsList.getMax("CASE_BGNG_YMD"); //입소일자
			    
			    var endDate = new Date(maxTrmnYmd.substring(0,4), maxTrmnYmd.substring(4,6), maxTrmnYmd.substring(6,8));
			    endDate.setFullYear(endDate.getFullYear() - 3); //최근퇴소일자 - 3년
			    var strDate = dateToString(endDate);  //date -> string 변환

			    dsList.setSort("CASE_BGNG_YMD");  //입소일자로 sorting
			    var succYear = ValueUtil.fixNumber(0);
			    var succMonth = ValueUtil.fixNumber(0);
			    var succDay = ValueUtil.fixNumber(0);
			    var sumYear = ValueUtil.fixNumber(0);
			    var sumMonth = ValueUtil.fixNumber(0);
			    var sumDay = ValueUtil.fixNumber(0);
			    
			    //시작일자, 종료일자, 쉼터, 연속여부
			    for (var i = 0; i < dsList.getRowCount(); i++){
			        var bgngYmd = ""; //입소일자
			        var trmnYmd = ""; //퇴소일자
			        var succYn = "" ; //연속여부

			        //입소일자
			        if (dsList.getValue(i, "CASE_BGNG_YMD") <= strDate){
			             bgngYmd = strDate;
			        } else {
			            bgngYmd = dsList.getValue(i, "CASE_BGNG_YMD");
			        }

			        var diffAfterDays = 0;
			        if (i + 1 == dsList.getRowCount()) {
			            diffAfterDays = 10; //마지막 행은 그행의 종료일자
			        } else {
			            diffAfterDays = moment(dsList.getValue(i+1, "CASE_BGNG_YMD")).diff(moment(dsList.getValue(i, "CASE_TRMN_YMD")), 'days');
			        }
			        
			        if (diffAfterDays < -1  ) {
			            util.Msg.alert(app, "WRN-M009", ["퇴소일", "이후 입소일"], function() {}, "경고");
			            return false;
			        }

			        //7일이내
			        if (diffAfterDays <= 7) {
			             trmnYmd = dsList.getValue(i+1, "CASE_BGNG_YMD");
			        } else {
			            trmnYmd = dsList.getValue(i, "CASE_TRMN_YMD");
			        }


			        var diffBeforeDays = 0;
			        if (i > 0) {
			            diffBeforeDays = moment(dsList.getValue(i, "CASE_BGNG_YMD")).diff(moment(dsList.getValue(i-1, "CASE_TRMN_YMD")), 'days');
			        }
			        
			        //연속여부
			        if (diffBeforeDays <= 7) {
			             succYn = "Y";
			        } else {
			             succYn = "N";
			        }

			        var rtnVal = getEntrncPrd(bgngYmd, trmnYmd);
			        
			        dsList.setValue(i, "ENTSC_PRD_YR", rtnVal["PRD_YR"]);
			        dsList.setValue(i, "ENTSC_PRD_MM", rtnVal["PRD_MM"]);
			        dsList.setValue(i, "ENTSC_PRD_DD", rtnVal["PRD_DD"]);

			        if (succYn == "N") {
			            succYear = ValueUtil.fixNumber(0);
			            succMonth = ValueUtil.fixNumber(0);
			            succDay = ValueUtil.fixNumber(0);
			        }

			        succYear += ValueUtil.fixNumber(dsList.getValue(i, "ENTSC_PRD_YR"));
			        sumYear += ValueUtil.fixNumber(dsList.getValue(i, "ENTSC_PRD_YR"));

			        succMonth += ValueUtil.fixNumber(dsList.getValue(i, "ENTSC_PRD_MM"));
			        sumMonth += ValueUtil.fixNumber(dsList.getValue(i, "ENTSC_PRD_MM"));

			        succDay += ValueUtil.fixNumber(dsList.getValue(i, "ENTSC_PRD_DD"));
			        sumDay += ValueUtil.fixNumber(dsList.getValue(i, "ENTSC_PRD_DD"));
			    }

			    sumMonth += parseInt(sumDay/30);
			    sumYear += parseInt(sumMonth/12);
			    
			    succMonth += parseInt(succDay/30);

			    //2년이상, 6개월이상
			    if ((succYear >= 1 || succMonth >= 6 ) && sumYear >= 2) {
			        dsList.setValue(0, "CTNUTN_ENTRNC_YN", "Y");        
			    } else {
			        dsList.setValue(0, "CTNUTN_ENTRNC_YN", "N");        
			    }
			    
			    dsList.setValue(0, "RECENT_PRD_YR", sumYear);
			    dsList.setValue(0, "RECENT_PRD_MM", sumMonth % 12);
			    dsList.setValue(0, "RECENT_PRD_DD", sumDay % 30);
			    
			//    console.log("sumDay : ", sumDay);
			//    console.log("sumMonth : ", sumMonth);
			//    console.log("sumYear : ", sumYear);
			//    
			//    console.log("succDay : ", succDay);
			//    console.log("succMonth : ", succMonth);
			//    console.log("succYear : ", succYear);
			    
			    return true;    
			}

			/**
			 * Date -> String 변환
			 * @param : date
			 */
			function dateToString(date){
			    return date.getFullYear() 
			         + (date.getMonth() < 9 ? "0" + (date.getMonth()) : (date.getMonth()))
			         + (date.getDate() < 9 ? "0" + (date.getDate()) : (date.getDate()));
			}

